import{_ as n,l as u,o as a,c as l,v as r,p as i,x as t,d as s,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"运行队列","description":"","frontmatter":{"title":"运行队列","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/runqueue.md","filePath":"cs/runqueue.md","lastUpdated":1789023840000}'),p={name:"cs/runqueue.md"};function h(_,e,m,P,q,C){const o=u("Mermaid");return a(),l("div",null,[e[1]||(e[1]=r('<h1 id="运行队列" tabindex="-1">运行队列 <a class="header-anchor" href="#运行队列" aria-label="Permalink to &quot;运行队列&quot;">​</a></h1><div class="epigraph"><p>调度器不是在全系统扫描 PCB；它只看运行队列里「可运行」的那些，每颗 CPU 还可以有自己的队列。</p><footer>—— 据 Love, Linux Kernel Development；Silberschatz et al. 整理</footer></div><p><a href="/cs/cpu-vs-io-bound">上一课</a>说明就绪者突发长度不同。<a href="/cs/idle-thread">idle 线程</a>在队列空时上场。缺口是<strong>运行队列（runqueue）</strong>：就绪且未在跑（或可被抢的）任务挂在这里，调度器 O(1) 或 O(log n) 取出下一个。阻塞的人在等待队列上，不在 runqueue。本课只钉这道数据结构，不比较 FCFS 与 SJF。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若每次时钟中断都遍历所有 PCB 找 <code>TASK_RUNNING</code>，核多任务多时不可扩展。<a href="/cs/percpu">per-CPU 数据</a> 已经暗示：每 CPU 一条 runqueue，本核调度只看本地，跨核靠后课迁移。缺口不是指标定义，而是「可运行集合」的显式容器：入队在唤醒与创建时，出队在睡眠与结束时。</p><p><span class="marginnote">正在本核运行的任务可视为队列的特殊成员或单独的 <code>current</code>。教学上把「可被选中的」都算进 runqueue 即可。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>单核教材：一条 FIFO 或按优先级的多槽。多核：每 CPU 本地队列 + 偶尔平衡。入队：唤醒路径把任务从等待队列挪到某 runqueue，必要时 IPI 踢目标核。出队：主动睡或被切走后若仍可运行则留在队列（抢占式轮转）。选下一个：按策略看队头或树的最左结点——策略是后课。</p>',8)),(a(),i(c,null,{default:t(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20WAKE%5B%22%E5%94%A4%E9%86%92%22%5D%20--%3E%20RQ%5B%22runqueue%22%5D%0A%20%20RQ%20--%3E%20PICK%5B%22%E8%B0%83%E5%BA%A6%E5%99%A8%E5%8F%96%E4%B8%8B%E4%B8%80%E4%B8%AA%22%5D%0A%20%20PICK%20--%3E%20SLEEP%5B%22%E9%98%BB%E5%A1%9E%3A%20%E7%A6%BB%E5%BC%80%20RQ%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>与<a href="/cs/pcb-task-struct">PCB</a> 的关系：PCB 上有「挂在哪条队列」的链指针；同一任务不能同时在两条 runqueue 上。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>runqueue 把调度从「哲学上选谁」变成「对这个容器操作」。I/O 型频繁入出队；CPU 型长时间占着 <code>current</code>。锁：操作某条队列要持该队列锁（或等价），不能在硬 IRQ 里乱入队而不标注上下文。具体锁是同步课；本课只要求队列是共享数据。</p><p>空队列 ⇒ idle。这把上一课 idle 接到容器上。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 CFS 红黑树或 EEVDF 的树当唯一实现，不写 <code>nr_running</code> 的所有会计。全局共享一条队列在多核上会成为锁热点，所以默认讲 per-CPU。亲和与迁移下一组课再收。</p><p>后课默认：可运行任务在 runqueue 上。按到达顺序或按长短来选队头，下一课讲 FCFS 与 SJF。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>runqueue 是可运行任务的容器；阻塞者不在其中。</li><li>多核上通常 per-CPU，以免扫描全世界。</li><li>队头如何定义是 FCFS/SJF 的缺口。</li><li>出处：Love, <em>LKD</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',9))])}const B=n(p,[["render",h]]);export{f as __pageData,B as default};
